type PageViewPayload = {
  path: string;
  title?: string;
};

export async function logPageView(payload: PageViewPayload) {
  const endpoint = process.env.ANALYTICS_ENDPOINT;

  if (!endpoint) {
    console.info("analytics: page_view", payload);
    return;
  }

  try {
    await fetch(endpoint, {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        ...payload,
        timestamp: Date.now(),
      }),
      cache: "no-store",
    });
  } catch (error) {
    console.error("analytics: page_view_failed", error);
  }
}

